 --- calculate_daily_cumulative_accumulation --- |                                                                                                                                                                          +
                                                 | DECLARE                                                                                                                                                                  +
                                                 |     v_step TEXT;                                                                                                                                                         +
                                                 |     v_start_time TIMESTAMP;                                                                                                                                              +
                                                 | BEGIN                                                                                                                                                                    +
                                                 |     v_start_time := clock_timestamp();                                                                                                                                   +
                                                 |     RAISE NOTICE 'Starting full calculation of daily_cumulative_accumulation at %', v_start_time;                                                                        +
                                                 |                                                                                                                                                                          +
                                                 |     v_step := 'Truncating target table';                                                                                                                                 +
                                                 |     RAISE NOTICE 'Step: %', v_step;                                                                                                                                      +
                                                 |     TRUNCATE TABLE daily_cumulative_accumulation;                                                                                                                        +
                                                 |                                                                                                                                                                          +
                                                 |     v_step := 'Calculating and inserting cumulative data';                                                                                                               +
                                                 |     RAISE NOTICE 'Step: %', v_step;                                                                                                                                      +
                                                 |     WITH daily_buy AS (                                                                                                                                                  +
                                                 |         -- Aggregate all buy transactions per entity, symbol, and day                                                                                                    +
                                                 |         SELECT                                                                                                                                                           +
                                                 |             df.transaction_date,                                                                                                                                         +
                                                 |             df.symbol,                                                                                                                                                   +
                                                 |             df.buyer_id AS entity_id,                                                                                                                                    +
                                                 |             SUM(df.transaction_quantity) AS total_buy_quantity,                                                                                                          +
                                                 |             SUM(df.transaction_quantity * df.transaction_rate) AS total_buy_amount                                                                                       +
                                                 |         FROM public.daily_floorsheet df                                                                                                                                  +
                                                 |         GROUP BY df.transaction_date, df.symbol, df.buyer_id                                                                                                             +
                                                 |     ),                                                                                                                                                                   +
                                                 |     daily_sell AS (                                                                                                                                                      +
                                                 |         -- Aggregate all sell transactions per entity, symbol, and day                                                                                                   +
                                                 |         SELECT                                                                                                                                                           +
                                                 |             df.transaction_date,                                                                                                                                         +
                                                 |             df.symbol,                                                                                                                                                   +
                                                 |             df.seller_id AS entity_id,                                                                                                                                   +
                                                 |             SUM(df.transaction_quantity) AS total_sell_quantity,                                                                                                         +
                                                 |             SUM(df.transaction_quantity * df.transaction_rate) AS total_sell_amount                                                                                      +
                                                 |         FROM public.daily_floorsheet df                                                                                                                                  +
                                                 |         GROUP BY df.transaction_date, df.symbol, df.seller_id                                                                                                            +
                                                 |     ),                                                                                                                                                                   +
                                                 |     daily_net_summary AS (                                                                                                                                               +
                                                 |         -- Combine buy and sell data to get the net change for each day                                                                                                  +
                                                 |         SELECT                                                                                                                                                           +
                                                 |             COALESCE(b.transaction_date, s.transaction_date) AS transaction_date,                                                                                        +
                                                 |             COALESCE(b.symbol, s.symbol) AS symbol,                                                                                                                      +
                                                 |             COALESCE(b.entity_id, s.entity_id) AS entity_id,                                                                                                             +
                                                 |             COALESCE(b.total_buy_quantity, 0) AS daily_buy,                                                                                                              +
                                                 |             COALESCE(b.total_buy_amount, 0) AS daily_buy_amount,                                                                                                         +
                                                 |             COALESCE(s.total_sell_quantity, 0) AS daily_sell,                                                                                                            +
                                                 |             COALESCE(s.total_sell_amount, 0) AS daily_sell_amount                                                                                                        +
                                                 |         FROM daily_buy b                                                                                                                                                 +
                                                 |         FULL OUTER JOIN daily_sell s                                                                                                                                     +
                                                 |             ON b.transaction_date = s.transaction_date                                                                                                                   +
                                                 |             AND b.symbol = s.symbol                                                                                                                                      +
                                                 |             AND b.entity_id = s.entity_id                                                                                                                                +
                                                 |     )                                                                                                                                                                    +
                                                 |     -- Insert the final calculated data, using window functions to create running totals                                                                                 +
                                                 |     INSERT INTO daily_cumulative_accumulation (                                                                                                                          +
                                                 |         transaction_date, symbol, entity_id,                                                                                                                             +
                                                 |         cumulative_buy, cumulative_buy_amount,                                                                                                                           +
                                                 |         cumulative_sell, cumulative_sell_amount,                                                                                                                         +
                                                 |         cumulative_net                                                                                                                                                   +
                                                 |     )                                                                                                                                                                    +
                                                 |     SELECT                                                                                                                                                               +
                                                 |         dns.transaction_date,                                                                                                                                            +
                                                 |         dns.symbol,                                                                                                                                                      +
                                                 |         dns.entity_id,                                                                                                                                                   +
                                                 |         SUM(dns.daily_buy) OVER (PARTITION BY dns.symbol, dns.entity_id ORDER BY dns.transaction_date) AS cumulative_buy,                                                +
                                                 |         SUM(dns.daily_buy_amount) OVER (PARTITION BY dns.symbol, dns.entity_id ORDER BY dns.transaction_date) AS cumulative_buy_amount,                                  +
                                                 |         SUM(dns.daily_sell) OVER (PARTITION BY dns.symbol, dns.entity_id ORDER BY dns.transaction_date) AS cumulative_sell,                                              +
                                                 |         SUM(dns.daily_sell_amount) OVER (PARTITION BY dns.symbol, dns.entity_id ORDER BY dns.transaction_date) AS cumulative_sell_amount,                                +
                                                 |         SUM(dns.daily_buy - dns.daily_sell) OVER (PARTITION BY dns.symbol, dns.entity_id ORDER BY dns.transaction_date) AS cumulative_net                                +
                                                 |     FROM daily_net_summary dns;                                                                                                                                          +
                                                 |                                                                                                                                                                          +
                                                 |     RAISE NOTICE 'Finished calculation in %', (clock_timestamp() - v_start_time);                                                                                        +
                                                 | EXCEPTION                                                                                                                                                                +
                                                 |     WHEN OTHERS THEN                                                                                                                                                     +
                                                 |         RAISE EXCEPTION 'PROCEDURE FAILED. Last step: %. Error: %', v_step, SQLERRM;                                                                                     +
                                                 | END;                                                                                                                                                                     +
                                                 | 
 --- load_broker_floorsheet_data ---             |                                                                                                                                                                          +
                                                 | DECLARE                                                                                                                                                                  +
                                                 |     v_step TEXT;                                                                                                                                                         +
                                                 |     v_start_time TIMESTAMP;                                                                                                                                              +
                                                 |     v_row_count INTEGER;                                                                                                                                                 +
                                                 | BEGIN                                                                                                                                                                    +
                                                 |     v_start_time := clock_timestamp();                                                                                                                                   +
                                                 |     RAISE NOTICE 'Starting full floorsheet data processing at %', v_start_time;                                                                                          +
                                                 |                                                                                                                                                                          +
                                                 |     v_step := 'Dropping existing indexes';                                                                                                                               +
                                                 |     RAISE NOTICE 'Step: %', v_step;                                                                                                                                      +
                                                 |     DROP INDEX IF EXISTS idx_buyer_floorsheet;                                                                                                                           +
                                                 |     DROP INDEX IF EXISTS idx_seller_floorsheet;                                                                                                                          +
                                                 |                                                                                                                                                                          +
                                                 |     v_step := 'Processing buyer data';                                                                                                                                   +
                                                 |     RAISE NOTICE 'Step: %', v_step;                                                                                                                                      +
                                                 |     TRUNCATE daily_buyer_floorsheet;                                                                                                                                     +
                                                 |     WITH buyer_daily_summary AS (                                                                                                                                        +
                                                 |         SELECT                                                                                                                                                           +
                                                 |             d.transaction_date,                                                                                                                                          +
                                                 |             d.symbol,                                                                                                                                                    +
                                                 |             d.buyer_id,                                                                                                                                                  +
                                                 |             SUM(d.transaction_quantity) AS daily_buy_volume,                                                                                                             +
                                                 |             SUM(d.transaction_quantity * d.transaction_rate) AS daily_buy_amount                                                                                         +
                                                 |         FROM "daily_floorsheet" d                                                                                                                                        +
                                                 |         GROUP BY d.transaction_date, d.symbol, d.buyer_id                                                                                                                +
                                                 |     ),                                                                                                                                                                   +
                                                 |     total_volumes AS (                                                                                                                                                   +
                                                 |         SELECT                                                                                                                                                           +
                                                 |             transaction_date,                                                                                                                                            +
                                                 |             symbol,                                                                                                                                                      +
                                                 |             SUM(transaction_quantity)::NUMERIC AS total_volume                                                                                                           +
                                                 |         FROM "daily_floorsheet"                                                                                                                                          +
                                                 |         GROUP BY transaction_date, symbol                                                                                                                                +
                                                 |     ),                                                                                                                                                                   +
                                                 |     ranked_buyers AS (                                                                                                                                                   +
                                                 |         SELECT                                                                                                                                                           +
                                                 |             bds.transaction_date,                                                                                                                                        +
                                                 |             bds.symbol,                                                                                                                                                  +
                                                 |             bds.buyer_id,                                                                                                                                                +
                                                 |             bds.daily_buy_volume::NUMERIC AS buy_volume,                                                                                                                 +
                                                 |             tv.total_volume,                                                                                                                                             +
                                                 |             (bds.daily_buy_volume / tv.total_volume) * 100 AS buy_volume_percentage,                                                                                     +
                                                 |             RANK() OVER (PARTITION BY bds.transaction_date, bds.symbol ORDER BY bds.daily_buy_volume DESC) AS buyer_rank,                                                +
                                                 |             CASE WHEN bds.daily_buy_volume > 0 THEN bds.daily_buy_amount / bds.daily_buy_volume ELSE 0 END AS average_weighted_price                                     +
                                                 |         FROM buyer_daily_summary bds                                                                                                                                     +
                                                 |         JOIN total_volumes tv ON bds.transaction_date = tv.transaction_date AND bds.symbol = tv.symbol                                                                   +
                                                 |     )                                                                                                                                                                    +
                                                 |     INSERT INTO DAILY_BUYER_FLOORSHEET (transaction_date, symbol, buyer_id, buy_volume, total_volume, buy_volume_percentage, buyer_rank, average_weighted_price)         +
                                                 |     SELECT transaction_date, symbol, buyer_id, buy_volume, total_volume, buy_volume_percentage, buyer_rank, average_weighted_price                                       +
                                                 |     FROM ranked_buyers;                                                                                                                                                  +
                                                 |     GET DIAGNOSTICS v_row_count = ROW_COUNT;                                                                                                                             +
                                                 |     RAISE NOTICE 'Inserted % rows into daily_buyer_floorsheet', v_row_count;                                                                                             +
                                                 |                                                                                                                                                                          +
                                                 |     v_step := 'Processing seller data';                                                                                                                                  +
                                                 |     RAISE NOTICE 'Step: %', v_step;                                                                                                                                      +
                                                 |     TRUNCATE daily_seller_floorsheet;                                                                                                                                    +
                                                 |     WITH seller_daily_summary AS (                                                                                                                                       +
                                                 |         SELECT                                                                                                                                                           +
                                                 |             d.transaction_date,                                                                                                                                          +
                                                 |             d.symbol,                                                                                                                                                    +
                                                 |             d.seller_id,                                                                                                                                                 +
                                                 |             SUM(d.transaction_quantity) AS daily_sell_volume,                                                                                                            +
                                                 |             SUM(d.transaction_quantity * d.transaction_rate) AS daily_sell_amount                                                                                        +
                                                 |         FROM "daily_floorsheet" d                                                                                                                                        +
                                                 |         GROUP BY d.transaction_date, d.symbol, d.seller_id                                                                                                               +
                                                 |     ),                                                                                                                                                                   +
                                                 |     total_volumes AS (                                                                                                                                                   +
                                                 |         SELECT                                                                                                                                                           +
                                                 |             transaction_date,                                                                                                                                            +
                                                 |             symbol,                                                                                                                                                      +
                                                 |             SUM(transaction_quantity)::NUMERIC AS total_volume                                                                                                           +
                                                 |         FROM "daily_floorsheet"                                                                                                                                          +
                                                 |         GROUP BY transaction_date, symbol                                                                                                                                +
                                                 |     ),                                                                                                                                                                   +
                                                 |     ranked_sellers AS (                                                                                                                                                  +
                                                 |         SELECT                                                                                                                                                           +
                                                 |             sds.transaction_date,                                                                                                                                        +
                                                 |             sds.symbol,                                                                                                                                                  +
                                                 |             sds.seller_id,                                                                                                                                               +
                                                 |             sds.daily_sell_volume::NUMERIC AS sell_volume,                                                                                                               +
                                                 |             tv.total_volume,                                                                                                                                             +
                                                 |             (sds.daily_sell_volume / tv.total_volume) * 100 AS sell_volume_percentage,                                                                                   +
                                                 |             RANK() OVER (PARTITION BY sds.transaction_date, sds.symbol ORDER BY sds.daily_sell_volume DESC) AS seller_rank,                                              +
                                                 |             CASE WHEN sds.daily_sell_volume > 0 THEN sds.daily_sell_amount / sds.daily_sell_volume ELSE 0 END AS average_weighted_price                                  +
                                                 |         FROM seller_daily_summary sds                                                                                                                                    +
                                                 |         JOIN total_volumes tv ON sds.transaction_date = tv.transaction_date AND sds.symbol = tv.symbol                                                                   +
                                                 |     )                                                                                                                                                                    +
                                                 |     INSERT INTO DAILY_SELLER_FLOORSHEET (transaction_date, symbol, seller_id, sell_volume, total_volume, sell_volume_percentage, seller_rank, average_weighted_price)    +
                                                 |     SELECT transaction_date, symbol, seller_id, sell_volume, total_volume, sell_volume_percentage, seller_rank, average_weighted_price                                   +
                                                 |     FROM ranked_sellers;                                                                                                                                                 +
                                                 |     GET DIAGNOSTICS v_row_count = ROW_COUNT;                                                                                                                             +
                                                 |     RAISE NOTICE 'Inserted % rows into daily_seller_floorsheet', v_row_count;                                                                                            +
                                                 |                                                                                                                                                                          +
                                                 |     v_step := 'Recreating indexes';                                                                                                                                      +
                                                 |     RAISE NOTICE 'Step: %', v_step;                                                                                                                                      +
                                                 |     CREATE INDEX idx_buyer_floorsheet ON daily_buyer_floorsheet(symbol, buyer_id, transaction_date);                                                                     +
                                                 |     CREATE INDEX idx_seller_floorsheet ON daily_seller_floorsheet(symbol, seller_id, transaction_date);                                                                  +
                                                 |                                                                                                                                                                          +
                                                 |     RAISE NOTICE 'Full floorsheet processing completed in %', (clock_timestamp() - v_start_time);                                                                        +
                                                 | EXCEPTION                                                                                                                                                                +
                                                 |     WHEN OTHERS THEN                                                                                                                                                     +
                                                 |         RAISE EXCEPTION 'PROCEDURE FAILED. Last step: %. Error: %', v_step, SQLERRM;                                                                                     +
                                                 | END;                                                                                                                                                                     +
                                                 | 
 --- refresh_broker_floorsheet_data ---          |                                                                                                                                                                          +
                                                 | DECLARE                                                                                                                                                                  +
                                                 |     v_step TEXT;                                                                                                                                                         +
                                                 |     v_start_time TIMESTAMP;                                                                                                                                              +
                                                 |     v_row_count INTEGER;                                                                                                                                                 +
                                                 |     v_today_date DATE;                                                                                                                                                   +
                                                 | BEGIN                                                                                                                                                                    +
                                                 |     v_start_time := clock_timestamp();                                                                                                                                   +
                                                 |     RAISE NOTICE 'Starting incremental floorsheet data processing at %', v_start_time;                                                                                   +
                                                 |                                                                                                                                                                          +
                                                 |     -- Use the latest date from the source transaction table to ensure data exists                                                                                       +
                                                 |     SELECT MAX(transaction_date) INTO v_today_date FROM "daily_floorsheet";                                                                                              +
                                                 |     RAISE NOTICE 'Processing data for date: %', v_today_date;                                                                                                            +
                                                 |                                                                                                                                                                          +
                                                 |     -- NOTE: Dropping/recreating indexes on every incremental refresh can be inefficient.                                                                                +
                                                 |     -- This is retained from the original logic but consider removing for better performance.                                                                            +
                                                 |     v_step := 'Dropping existing indexes';                                                                                                                               +
                                                 |     RAISE NOTICE 'Step: %', v_step;                                                                                                                                      +
                                                 |     BEGIN                                                                                                                                                                +
                                                 |         DROP INDEX IF EXISTS idx_buyer_floorsheet;                                                                                                                       +
                                                 |         DROP INDEX IF EXISTS idx_seller_floorsheet;                                                                                                                      +
                                                 |     EXCEPTION                                                                                                                                                            +
                                                 |         WHEN OTHERS THEN                                                                                                                                                 +
                                                 |             RAISE EXCEPTION 'Error during %: %', v_step, SQLERRM;                                                                                                        +
                                                 |     END;                                                                                                                                                                 +
                                                 |     RAISE NOTICE 'Completed % successfully', v_step;                                                                                                                     +
                                                 |                                                                                                                                                                          +
                                                 |                                                                                                                                                                          +
                                                 |     v_step := 'Processing buyer data for today with UPSERT';                                                                                                             +
                                                 |     RAISE NOTICE 'Step: %', v_step;                                                                                                                                      +
                                                 |     BEGIN                                                                                                                                                                +
                                                 |         WITH buyer_daily_summary AS (                                                                                                                                    +
                                                 |             SELECT                                                                                                                                                       +
                                                 |                 d.transaction_date,                                                                                                                                      +
                                                 |                 d.symbol,                                                                                                                                                +
                                                 |                 d.buyer_id,                                                                                                                                              +
                                                 |                 SUM(d.transaction_quantity) AS daily_buy_volume,                                                                                                         +
                                                 |                 SUM(d.transaction_quantity * d.transaction_rate) AS daily_buy_amount                                                                                     +
                                                 |             FROM "daily_floorsheet" d                                                                                                                                    +
                                                 |             WHERE d.transaction_date = v_today_date                                                                                                                      +
                                                 |             GROUP BY d.transaction_date, d.symbol, d.buyer_id                                                                                                            +
                                                 |         ),                                                                                                                                                               +
                                                 |         total_volumes AS (                                                                                                                                               +
                                                 |             SELECT                                                                                                                                                       +
                                                 |                 transaction_date,                                                                                                                                        +
                                                 |                 symbol,                                                                                                                                                  +
                                                 |                 SUM(transaction_quantity)::NUMERIC AS total_volume                                                                                                       +
                                                 |             FROM "daily_floorsheet"                                                                                                                                      +
                                                 |             WHERE transaction_date = v_today_date                                                                                                                        +
                                                 |             GROUP BY transaction_date, symbol                                                                                                                            +
                                                 |         ),                                                                                                                                                               +
                                                 |         ranked_buyers AS (                                                                                                                                               +
                                                 |             SELECT                                                                                                                                                       +
                                                 |                 bds.transaction_date,                                                                                                                                    +
                                                 |                 bds.symbol,                                                                                                                                              +
                                                 |                 bds.buyer_id,                                                                                                                                            +
                                                 |                 bds.daily_buy_volume::NUMERIC AS buy_volume,                                                                                                             +
                                                 |                 tv.total_volume,                                                                                                                                         +
                                                 |                 (bds.daily_buy_volume / tv.total_volume) * 100 AS buy_volume_percentage,                                                                                 +
                                                 |                 RANK() OVER (PARTITION BY bds.transaction_date, bds.symbol ORDER BY bds.daily_buy_volume DESC) AS buyer_rank,                                            +
                                                 |                 CASE WHEN bds.daily_buy_volume > 0 THEN bds.daily_buy_amount / bds.daily_buy_volume ELSE 0 END AS average_weighted_price                                 +
                                                 |             FROM buyer_daily_summary bds                                                                                                                                 +
                                                 |             JOIN total_volumes tv ON bds.transaction_date = tv.transaction_date AND bds.symbol = tv.symbol                                                               +
                                                 |         )                                                                                                                                                                +
                                                 |         INSERT INTO DAILY_BUYER_FLOORSHEET (transaction_date, symbol, buyer_id, buy_volume, total_volume, buy_volume_percentage, buyer_rank, average_weighted_price)     +
                                                 |         SELECT transaction_date, symbol, buyer_id, buy_volume, total_volume, buy_volume_percentage, buyer_rank, average_weighted_price                                   +
                                                 |         FROM ranked_buyers                                                                                                                                               +
                                                 |         ON CONFLICT (transaction_date, symbol, buyer_id) DO UPDATE SET                                                                                                   +
                                                 |             buy_volume = EXCLUDED.buy_volume,                                                                                                                            +
                                                 |             total_volume = EXCLUDED.total_volume,                                                                                                                        +
                                                 |             buy_volume_percentage = EXCLUDED.buy_volume_percentage,                                                                                                      +
                                                 |             buyer_rank = EXCLUDED.buyer_rank,                                                                                                                            +
                                                 |             average_weighted_price = EXCLUDED.average_weighted_price;                                                                                                    +
                                                 |         GET DIAGNOSTICS v_row_count = ROW_COUNT;                                                                                                                         +
                                                 |         RAISE NOTICE 'Processed % rows in daily_buyer_floorsheet for date %', v_row_count, v_today_date;                                                                 +
                                                 |     EXCEPTION                                                                                                                                                            +
                                                 |         WHEN OTHERS THEN                                                                                                                                                 +
                                                 |             RAISE EXCEPTION 'Error during %: %', v_step, SQLERRM;                                                                                                        +
                                                 |     END;                                                                                                                                                                 +
                                                 |     RAISE NOTICE 'Completed % successfully', v_step;                                                                                                                     +
                                                 |                                                                                                                                                                          +
                                                 |                                                                                                                                                                          +
                                                 |     v_step := 'Processing seller data for today with UPSERT';                                                                                                            +
                                                 |     RAISE NOTICE 'Step: %', v_step;                                                                                                                                      +
                                                 |     BEGIN                                                                                                                                                                +
                                                 |         WITH seller_daily_summary AS (                                                                                                                                   +
                                                 |             SELECT                                                                                                                                                       +
                                                 |                 d.transaction_date,                                                                                                                                      +
                                                 |                 d.symbol,                                                                                                                                                +
                                                 |                 d.seller_id,                                                                                                                                             +
                                                 |                 SUM(d.transaction_quantity) AS daily_sell_volume,                                                                                                        +
                                                 |                 SUM(d.transaction_quantity * d.transaction_rate) AS daily_sell_amount                                                                                    +
                                                 |             FROM "daily_floorsheet" d                                                                                                                                    +
                                                 |             WHERE d.transaction_date = v_today_date                                                                                                                      +
                                                 |             GROUP BY d.transaction_date, d.symbol, d.seller_id                                                                                                           +
                                                 |         ),                                                                                                                                                               +
                                                 |         total_volumes AS (                                                                                                                                               +
                                                 |             SELECT                                                                                                                                                       +
                                                 |                 transaction_date,                                                                                                                                        +
                                                 |                 symbol,                                                                                                                                                  +
                                                 |                 SUM(transaction_quantity)::NUMERIC AS total_volume                                                                                                       +
                                                 |             FROM "daily_floorsheet"                                                                                                                                      +
                                                 |             WHERE transaction_date = v_today_date                                                                                                                        +
                                                 |             GROUP BY transaction_date, symbol                                                                                                                            +
                                                 |         ),                                                                                                                                                               +
                                                 |         ranked_sellers AS (                                                                                                                                              +
                                                 |             SELECT                                                                                                                                                       +
                                                 |                 sds.transaction_date,                                                                                                                                    +
                                                 |                 sds.symbol,                                                                                                                                              +
                                                 |                 sds.seller_id,                                                                                                                                           +
                                                 |                 sds.daily_sell_volume::NUMERIC AS sell_volume,                                                                                                           +
                                                 |                 tv.total_volume,                                                                                                                                         +
                                                 |                 (sds.daily_sell_volume / tv.total_volume) * 100 AS sell_volume_percentage,                                                                               +
                                                 |                 RANK() OVER (PARTITION BY sds.transaction_date, sds.symbol ORDER BY sds.daily_sell_volume DESC) AS seller_rank,                                          +
                                                 |                 CASE WHEN sds.daily_sell_volume > 0 THEN sds.daily_sell_amount / sds.daily_sell_volume ELSE 0 END AS average_weighted_price                              +
                                                 |             FROM seller_daily_summary sds                                                                                                                                +
                                                 |             JOIN total_volumes tv ON sds.transaction_date = tv.transaction_date AND sds.symbol = tv.symbol                                                               +
                                                 |         )                                                                                                                                                                +
                                                 |         INSERT INTO DAILY_SELLER_FLOORSHEET (transaction_date, symbol, seller_id, sell_volume, total_volume, sell_volume_percentage, seller_rank, average_weighted_price)+
                                                 |         SELECT transaction_date, symbol, seller_id, sell_volume, total_volume, sell_volume_percentage, seller_rank, average_weighted_price                               +
                                                 |         FROM ranked_sellers                                                                                                                                              +
                                                 |         ON CONFLICT (transaction_date, symbol, seller_id) DO UPDATE SET                                                                                                  +
                                                 |             sell_volume = EXCLUDED.sell_volume,                                                                                                                          +
                                                 |             total_volume = EXCLUDED.total_volume,                                                                                                                        +
                                                 |             sell_volume_percentage = EXCLUDED.sell_volume_percentage,                                                                                                    +
                                                 |             seller_rank = EXCLUDED.seller_rank,                                                                                                                          +
                                                 |             average_weighted_price = EXCLUDED.average_weighted_price;                                                                                                    +
                                                 |         GET DIAGNOSTICS v_row_count = ROW_COUNT;                                                                                                                         +
                                                 |         RAISE NOTICE 'Processed % rows in daily_seller_floorsheet for date %', v_row_count, v_today_date;                                                                +
                                                 |     EXCEPTION                                                                                                                                                            +
                                                 |         WHEN OTHERS THEN                                                                                                                                                 +
                                                 |             RAISE EXCEPTION 'Error during %: %', v_step, SQLERRM;                                                                                                        +
                                                 |     END;                                                                                                                                                                 +
                                                 |     RAISE NOTICE 'Completed % successfully', v_step;                                                                                                                     +
                                                 |                                                                                                                                                                          +
                                                 |     v_step := 'Recreating indexes';                                                                                                                                      +
                                                 |     RAISE NOTICE 'Step: %', v_step;                                                                                                                                      +
                                                 |     BEGIN                                                                                                                                                                +
                                                 |         CREATE INDEX idx_buyer_floorsheet ON daily_buyer_floorsheet(symbol, buyer_id, transaction_date);                                                                 +
                                                 |         CREATE INDEX idx_seller_floorsheet ON daily_seller_floorsheet(symbol, seller_id, transaction_date);                                                              +
                                                 |     EXCEPTION                                                                                                                                                            +
                                                 |         WHEN OTHERS THEN                                                                                                                                                 +
                                                 |             RAISE EXCEPTION 'Error during %: %', v_step, SQLERRM;                                                                                                        +
                                                 |     END;                                                                                                                                                                 +
                                                 |     RAISE NOTICE 'Completed % successfully', v_step;                                                                                                                     +
                                                 |                                                                                                                                                                          +
                                                 |     RAISE NOTICE 'Incremental floorsheet processing completed successfully in %', (clock_timestamp() - v_start_time);                                                    +
                                                 | EXCEPTION                                                                                                                                                                +
                                                 |     WHEN OTHERS THEN                                                                                                                                                     +
                                                 |         RAISE EXCEPTION 'PROCEDURE FAILED. Last step: %. Error: %', v_step, SQLERRM;                                                                                     +
                                                 | END;                                                                                                                                                                     +
                                                 | 
 --- update_daily_floorsheet_details ---         |                                                                                                                                                                          +
                                                 | DECLARE                                                                                                                                                                  +
                                                 |     max_transaction_date DATE;                                                                                                                                           +
                                                 | BEGIN                                                                                                                                                                    +
                                                 |     -- Get the maximum transaction date from the daily_stock_price table                                                                                                 +
                                                 |     SELECT MAX(transaction_date) INTO max_transaction_date FROM daily_stock_price;                                                                                       +
                                                 |                                                                                                                                                                          +
                                                 |     -- Insert or update for buyer                                                                                                                                        +
                                                 |     INSERT INTO DAILY_BUYER_FLOORSHEET_DETAIL (transaction_date, symbol, buyer_id, buy_volume, total_volume, buy_volume_percentage, buyer_rank)                          +
                                                 |     SELECT                                                                                                                                                               +
                                                 |         d."businessDate" AS transaction_date,                                                                                                                            +
                                                 |         d."stockSymbol" AS symbol,                                                                                                                                       +
                                                 |         d."buyerMemberId" AS buyer_id,                                                                                                                                   +
                                                 |         SUM(d."contractQuantity") AS buy_volume,                                                                                                                         +
                                                 |         AVG(t.total_volume) AS total_volume,                                                                                                                             +
                                                 |         SUM(d."contractQuantity") / AVG(t.total_volume) * 100 AS buy_volume_percentage,                                                                                  +
                                                 |         RANK() OVER (PARTITION BY d."businessDate", d."stockSymbol" ORDER BY SUM(d."contractQuantity") DESC) AS buyer_rank                                               +
                                                 |     FROM                                                                                                                                                                 +
                                                 |         "daily_floorsheet_detail" d                                                                                                                                      +
                                                 |     JOIN (                                                                                                                                                               +
                                                 |         SELECT                                                                                                                                                           +
                                                 |             "businessDate",                                                                                                                                              +
                                                 |             "stockSymbol",                                                                                                                                               +
                                                 |             SUM("contractQuantity") AS total_volume                                                                                                                      +
                                                 |         FROM                                                                                                                                                             +
                                                 |             "daily_floorsheet_detail"                                                                                                                                    +
                                                 |         WHERE "businessDate" = max_transaction_date                                                                                                                      +
                                                 |         GROUP BY                                                                                                                                                         +
                                                 |             "businessDate", "stockSymbol"                                                                                                                                +
                                                 |     ) t ON d."businessDate" = t."businessDate" AND d."stockSymbol" = t."stockSymbol"                                                                                     +
                                                 |     WHERE d."businessDate" = max_transaction_date                                                                                                                        +
                                                 |     GROUP BY                                                                                                                                                             +
                                                 |         d."businessDate", d."stockSymbol", d."buyerMemberId"                                                                                                             +
                                                 |     ON CONFLICT (transaction_date, symbol, buyer_id) DO UPDATE                                                                                                           +
                                                 |     SET                                                                                                                                                                  +
                                                 |         buy_volume = EXCLUDED.buy_volume,                                                                                                                                +
                                                 |         total_volume = EXCLUDED.total_volume,                                                                                                                            +
                                                 |         buy_volume_percentage = EXCLUDED.buy_volume_percentage,                                                                                                          +
                                                 |         buyer_rank = EXCLUDED.buyer_rank;                                                                                                                                +
                                                 |                                                                                                                                                                          +
                                                 |     -- Insert or update for seller                                                                                                                                       +
                                                 |     INSERT INTO DAILY_SELLER_FLOORSHEET_DETAIL (transaction_date, symbol, seller_id, sell_volume, total_volume, sell_volume_percentage, seller_rank)                     +
                                                 |     SELECT                                                                                                                                                               +
                                                 |         d."businessDate" AS transaction_date,                                                                                                                            +
                                                 |         d."stockSymbol" AS symbol,                                                                                                                                       +
                                                 |         d."sellerMemberId" AS seller_id,                                                                                                                                 +
                                                 |         SUM(d."contractQuantity") AS sell_volume,                                                                                                                        +
                                                 |         AVG(t.total_volume) AS total_volume,                                                                                                                             +
                                                 |         SUM(d."contractQuantity") / AVG(t.total_volume) * 100 AS sell_volume_percentage,                                                                                 +
                                                 |         RANK() OVER (PARTITION BY d."businessDate", d."stockSymbol" ORDER BY SUM(d."contractQuantity") DESC) AS seller_rank                                              +
                                                 |     FROM                                                                                                                                                                 +
                                                 |         "daily_floorsheet_detail" d                                                                                                                                      +
                                                 |     JOIN (                                                                                                                                                               +
                                                 |         SELECT                                                                                                                                                           +
                                                 |             "businessDate",                                                                                                                                              +
                                                 |             "stockSymbol",                                                                                                                                               +
                                                 |             SUM("contractQuantity") AS total_volume                                                                                                                      +
                                                 |         FROM                                                                                                                                                             +
                                                 |             "daily_floorsheet_detail"                                                                                                                                    +
                                                 |         WHERE "businessDate" = max_transaction_date                                                                                                                      +
                                                 |         GROUP BY                                                                                                                                                         +
                                                 |             "businessDate", "stockSymbol"                                                                                                                                +
                                                 |     ) t ON d."businessDate" = t."businessDate" AND d."stockSymbol" = t."stockSymbol"                                                                                     +
                                                 |     WHERE d."businessDate" = max_transaction_date                                                                                                                        +
                                                 |     GROUP BY                                                                                                                                                             +
                                                 |         d."businessDate", d."stockSymbol", d."sellerMemberId"                                                                                                            +
                                                 |     ON CONFLICT (transaction_date, symbol, seller_id) DO UPDATE                                                                                                          +
                                                 |     SET                                                                                                                                                                  +
                                                 |         sell_volume = EXCLUDED.sell_volume,                                                                                                                              +
                                                 |         total_volume = EXCLUDED.total_volume,                                                                                                                            +
                                                 |         sell_volume_percentage = EXCLUDED.sell_volume_percentage,                                                                                                        +
                                                 |         seller_rank = EXCLUDED.seller_rank;                                                                                                                              +
                                                 | END;                                                                                                                                                                     +
